package com.eventfinder.controller;
import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/registrations") public class RegistrationController {private final JdbcTemplate db;public RegistrationController(JdbcTemplate d){db=d;}@PostMapping public ResponseEntity<?> register(@RequestBody Map<String,Long> body,Authentication a){long uid=user(a);long eid=body.get("eventId");Integer cap=db.queryForObject("SELECT capacity FROM events WHERE id=? AND event_date>=CURDATE()",Integer.class,eid);if(cap==null)throw new NoSuchElementException("Event not found or registration closed");Integer count=db.queryForObject("SELECT COUNT(*) FROM registrations WHERE event_id=? AND status='CONFIRMED'",Integer.class,eid);if(count>=cap)throw new IllegalArgumentException("This event is full");Integer exists=db.queryForObject("SELECT COUNT(*) FROM registrations WHERE event_id=? AND user_id=?",Integer.class,eid,uid);if(exists>0)throw new IllegalArgumentException("You are already registered for this event");db.update("INSERT INTO registrations(event_id,user_id,status) VALUES(?,?,'CONFIRMED')",eid,uid);return ResponseEntity.status(201).body(Map.of("message","Registration confirmed"));}@GetMapping("/my") public List<Map<String,Object>> mine(Authentication a){return db.queryForList("SELECT r.id registration_id,r.status,e.id event_id,e.title,e.event_date,e.start_time,e.venue,e.location,e.image_url FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.user_id=? ORDER BY e.event_date",user(a));}@DeleteMapping("/{id}") public ResponseEntity<Void> cancel(@PathVariable long id,Authentication a){int n=db.update("DELETE FROM registrations WHERE id=? AND user_id=?",id,user(a));if(n==0)throw new NoSuchElementException("Registration not found");return ResponseEntity.noContent().build();}private long user(Authentication a){return db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,a.getName());}}